const mirrorReflectDeg = (deg) => {
  let d = 180 - deg;
  while (d > 180) d -= 360;
  while (d <= -180) d += 360;
  return d;
};
const median = (arr) => { const s = [...arr].sort((a,b)=>a-b); const m = s.length; return m % 2 ? s[(m-1)/2] : (s[m/2-1]+s[m/2])/2; };
const stdOf = (arr) => { const m = arr.reduce((a,b)=>a+b,0)/arr.length; const v = arr.reduce((a,b)=>a+(b-m)**2,0)/arr.length; return { mean: m, std: Math.sqrt(v) }; };
const rgbToHex = (r,g,b) => { const h = (n) => Math.round(Math.max(0,Math.min(255,n))).toString(16).padStart(2,'0'); return `#${h(r)}${h(g)}${h(b)}`; };
const clamp01 = (n) => Math.max(0, Math.min(1, n));
const gaussianBump = (x, mu, sigma) => { const z = (x-mu)/sigma; return Math.exp(-0.5*z*z); };

