function calculateEyeLashMap(entry, c, side) {
  const eye = side === 'left' ? c.leftEye : c.rightEye;
  const other = side === 'left' ? c.rightEye : c.leftEye;
  const physicalTilt = c.perEyeTiltDegrees?.[side]
    ?? (side === 'left' ? eye.tiltCorrected : mirrorReflectDeg(eye.tiltCorrected));

  // The catalog supplies only design intent. The peak and all five
  // lengths are rebuilt independently from this eye's measurements.
  let peakZone = entry.peakZone;
  // Domain decision: Fox's professionally authored outer/pre-outer
  // peak (zonePositions[3] = 0.85) must survive upturned tilt, not
  // be silently demoted to BODY. This exemption applies to Fox only.
  if (entry.id !== 'fox' && physicalTilt > 4 && peakZone > 1) peakZone -= 1;
  if (physicalTilt < -4 && peakZone < 3 && entry.category !== 'correction') peakZone += 1;

  const avgWidth = Math.max((eye.width + other.width) / 2, 1);
  const widthScale = clamp01(0.5 + eye.width / avgWidth / 2);
  const openingScale = clamp01((eye.ear - 0.14) / 0.22);
  const sizeScale = clamp01((c.relativeEyeSize - 0.26) / 0.16);
  const peakLength = Math.round(Math.max(8, Math.min(13,
    8.5 + sizeScale * 2.2 + widthScale * 1.1 + openingScale * 0.7
  )));
  const template=entry.baseZones,templatePeak=entry.peakZone,templatePeakLength=template[templatePeak];
  const profilePeakLength=Math.max(peakLength,5+templatePeakLength-Math.min(...template));
  const sampleTemplate=x=>{
    const lo=Math.max(0,Math.min(4,Math.floor(x))),hi=Math.max(0,Math.min(4,Math.ceil(x)));
    if(lo===hi)return template[lo];
    return template[lo]+(template[hi]-template[lo])*(x-lo)/(hi-lo);
  };
  // Move the complete professional profile with the measured peak:
  // each side is independently stretched/compressed around PEAK,
  // preserving TRANSITION/BODY/shoulder intent instead of rebuilding
  // a generic linear ramp from only the two endpoint drops.
  const warpedTemplate=Array.from({length:5},(_,i)=>{
    if(i===peakZone)return templatePeakLength;
    if(i<peakZone)return sampleTemplate(templatePeak*i/Math.max(peakZone,1));
    return sampleTemplate(templatePeak+(4-templatePeak)*(i-peakZone)/Math.max(4-peakZone,1));
  });
  const innerAdjustment=(c.isCloseSet?1:0)+(eye.innerTaperDeg<55?1:0);
  const outerAdjustment=(physicalTilt>4?1:0)+(eye.outerTaperDeg>80?1:0);
  const zones=warpedTemplate.map((v,i)=>{
    const profileLength=profilePeakLength+(v-templatePeakLength);
    const innerPenalty=i<peakZone?innerAdjustment*(peakZone-i)/Math.max(peakZone,1):0;
    const outerPenalty=i>peakZone?outerAdjustment*(i-peakZone)/Math.max(4-peakZone,1):0;
    return Math.max(5,Math.round(profileLength-innerPenalty-outerPenalty));
  });

  const widthDeficit = Math.max(0, (other.width - eye.width) / Math.max(other.width, 1));
  const openingDeficit = Math.max(0, (other.ear - eye.ear) / Math.max(other.ear, 0.01));
  const measuredCorrection = clamp01(widthDeficit * 0.65 + openingDeficit * 0.35);
  const correctionMm = c.compositeAsymmetry > 0.07 && measuredCorrection > 0.04
    ? Math.min(2, Math.max(1, Math.round(measuredCorrection * (entry.correctionMultiplier || 1) * 4)))
    : 0;
  if (correctionMm > 0) {
    zones[peakZone] = Math.min(14, zones[peakZone] + correctionMm);
    const neighbour = peakZone === 4 ? 3 : peakZone + 1;
    zones[neighbour] = Math.min(zones[peakZone], zones[neighbour] + Math.max(0, correctionMm - 1));
  }
  return { zones, peakZone, correctionMm };
}

function buildEyeZones(entry, c) {
  const left = calculateEyeLashMap(entry, c, 'left');
  const right = calculateEyeLashMap(entry, c, 'right');
  return { left: left.zones, right: right.zones, leftPeakZone: left.peakZone, rightPeakZone: right.peakZone, leftCorrectionMm: left.correctionMm, rightCorrectionMm: right.correctionMm };
}
